using System;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using Codice.Characters;using Codice.Presentation;using Codice.UI;
public static class VerifyFullBodyActions{
 static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 public static async Task<string> Run(){
 var p=RunHUD.Instance.Player;var combat=p.GetComponent<PlayerCombat>();var ap=p.GetComponent<ActorPresentation>();p.SetNarrativeControlsBlocked(false);RunHUD.Instance.SetPaused(false);p.enabled=false;combat.enabled=false;
 try{
 p.State.EquipIntoSlot(new WeaponInstance(WeaponKind.Sword),0);p.State.EquipIntoSlot(new WeaponInstance(WeaponKind.Sword),1);p.State.SelectWeapon(0);combat.GetType().GetMethod("UpdateWeapon",F).Invoke(combat,new object[]{p.State.ActiveWeapon});combat.GetType().GetField("nextAttack",F).SetValue(combat,0f);Check(combat.TryAttack(),"Dual attack rejected");Vector3 before=p.transform.position;for(int i=0;i<10;i++)p.SimulateMotor(Vector3.forward,true,1f/60);Check(Vector3.ProjectOnPlane(p.transform.position-before,Vector3.up).magnitude<.001f,"Dual attack slides");for(int i=1;i<ap.Body.layerCount;i++)Check(ap.Body.GetLayerWeight(i)==0,"Overlay masks dual attack");combat.GetType().GetMethod("InterruptCombo",F).Invoke(combat,null);
 foreach(string state in new[]{"SwordCombo1","DualSlice","DualStab"}){ap.Body.Play(state,0,.1f);ap.Body.Update(0);var knee=ap.Body.GetBoneTransform(HumanBodyBones.LeftLowerLeg);var right=ap.Body.GetBoneTransform(HumanBodyBones.RightLowerLeg);var a=knee.localRotation;var b=right.localRotation;ap.Body.Play(state,0,.55f);ap.Body.Update(0);Check(Quaternion.Angle(a,knee.localRotation)+Quaternion.Angle(b,right.localRotation)>1,"Leg muscles static in "+state);}
 var book=p.GetComponent<RunSpellbook>();book.Learn(RunSpell.Fire);book.Ready=0;p.State.RestoreMana(200);Check(book.Cast(),"Spell rejected");await Task.Delay(250);Check(book.Casting,"Spell unlocks at release instead of recovery");before=p.transform.position;for(int i=0;i<10;i++)p.SimulateMotor(Vector3.forward,true,1f/60);Check(Vector3.ProjectOnPlane(p.transform.position-before,Vector3.up).magnitude<.001f,"Casting slides");await Task.Delay(600);Check(!book.Casting,"Spell movement stays locked");Debug.Log("PASS sword/dual knee motion, zero masked layers, stationary dual strike and spell recovery unlock");return "PASS animated knees, stationary dual attack, no overlays, stationary spell until recovery";
 }finally{p.enabled=true;combat.enabled=true;ap.Body.speed=1;}
 }
}
